.darma-loader-tw-heart-beat { position: relative; display: inline-block; width: var(--loader-size, 56px); height: var(--loader-size, 56px); animation: darma-loader-tw-heart-beat-twHeart calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
.darma-loader-tw-heart-beat::before, .darma-loader-tw-heart-beat::after { content: ''; position: absolute; top: 18%; width: 50%; height: 76%; border-radius: calc(var(--loader-size, 56px) * .5) calc(var(--loader-size, 56px) * .5) 0 0; background: var(--loader-color, #f43f5e); }
.darma-loader-tw-heart-beat::before { left: 50%; transform: rotate(-45deg); transform-origin: 0 100%; }
.darma-loader-tw-heart-beat::after { left: 0; transform: rotate(45deg); transform-origin: 100% 100%; }
@keyframes darma-loader-tw-heart-beat-twHeart { 0%, 100% { transform: scale(.84); } 15% { transform: scale(1.06); } 30% { transform: scale(.92); } 45% { transform: scale(1); } }

